<script setup lang="ts">
import {onMounted,ref,onUnmounted} from 'vue';
import {api,apiMessage} from '@/api/client';
import {capabilityGuide,healthSummary} from '@/helpModel';
import {getDesktopInfo,isNativeClient,isAndroid} from '@/desktop';
import {useAuthStore} from '@/stores/auth';
import {version} from '../../package.json';
const auth=useAuthStore(),health=ref<ReturnType<typeof healthSummary>|null>(null),error=ref(''),busy=ref(false),checked=ref(''),installed=ref(''),alive=ref(true);
onUnmounted(()=>{alive.value=false;});
onMounted(async()=>{if(isNativeClient())try{const info=await getDesktopInfo();if(alive.value)installed.value=info.version;}catch{/* Unknown is not an installed version. */}});
async function check(){if(busy.value)return;busy.value=true;error.value='';health.value=null;checked.value='';try{const value=healthSummary((await api.get('/health',{timeout:5000})).data);if(alive.value){health.value=value;checked.value=new Date().toLocaleString('zh-CN');}}catch(e){if(alive.value)error.value=apiMessage(e);}finally{if(alive.value)busy.value=false;}}
</script>
<template>
  <div class="page help-page">
    <header class="page-head"><div><h1>帮助与版本</h1><p>从选一种规划方式开始。这里也说明数据保存、离线和更新的边界。</p></div><router-link class="btn" :to="auth.user?'/learn':'/login'">{{auth.user?'打开使用教学':'返回登录'}}</router-link></header>
    <section class="help-start"><div class="help-number" aria-hidden="true">01</div><div><h2>先看一段本地演示</h2><p>用合成案例体验周期计划、目标路线和今日待办；AI 部分为固定示例，不调用接口、不扣次数，也不改变你的计划。</p><router-link class="btn primary" to="/help/demo">开始 3—5 分钟演示</router-link></div></section>
    <section class="section" aria-labelledby="help-version"><header class="section-title"><h2 id="help-version">当前设备与服务器</h2><button class="btn" type="button" :disabled="busy" @click="check">{{busy?'检查中…':'检查服务器版本'}}</button></header><div class="help-version-grid"><div><span>页面资源</span><strong>{{version}}</strong><p>{{isNativeClient()?(isAndroid()?'Android':'Windows'):'Web / PWA'}} · {{isNativeClient()?`安装版本：${installed||'尚未读取'}`:'浏览器页面，没有原生安装版本'}}</p></div><div aria-live="polite"><span>服务器 API</span><strong>{{health?health.version:'尚未确认'}}</strong><p v-if="health">API {{health.apiVersion}} · 本次检查 {{checked}}</p><p v-else>只报告实际检查结果；未检查或离线不代表服务正常。</p><p v-if="error" class="error-text">{{error}}</p></div></div><p class="help-note">页面与安装包版本相同不代表服务器已升级。此处检查不下载更新、不更改连接，也不证明全部业务健康。原生客户端更新仍在“客户端”页面主动检查，自动下载默认关闭。</p><router-link v-if="isNativeClient()" class="btn help-client-link" to="/desktop">客户端连接与更新</router-link></section>
    <section class="section" aria-labelledby="capability-guide"><header class="section-title"><h2 id="capability-guide">功能与边界</h2></header><p class="help-note">以下为本客户端的功能说明，Web、Windows 和 Android 共用业务代码。具体开放情况取决于服务器配置和账号权限，不能据此认定候选包已完成真机验收。</p><div class="help-capabilities"><article v-for="item in capabilityGuide" :key="item.name"><span>{{item.scope}}</span><h3>{{item.name}}</h3><p>{{item.detail}}</p><router-link v-if="auth.user" :to="item.path">前往功能</router-link></article></div></section>
    <section class="section help-answers"><h2>使用中遇到问题</h2><details><summary>页面显示连接失败怎么办？</summary><p>先检查网络，再在原生客户端核对 HTTPS 服务器地址和证书；不要关闭证书校验。网页登录失败可重新检查连接。仍无法恢复时，保存本机草稿并通过反馈提供错误分类和发生时间，不要发送密码。</p></details><details><summary>离线操作会自动同步吗？</summary><p>本机队列与云端数据分开保存。联网后进入同步中心核对；冲突需要人工处理。备份不包含未提交队列，不能通过清队列来修复连接或导出。</p></details><details><summary>为什么不能直接注册或公开下载 APK？</summary><p>当前为受邀试用，管理员下发邀请。Android 仅受限分发并登录后检查更新，官网不提供 APK 或二维码。网页、APP 及相关备案和公开发布门槛独立处理。</p></details><details><summary>管理员能看到我的私人计划吗？</summary><p>管理入口提供账号状态、邀请、额度、反馈处理与运行证据，不提供其他用户私人计划或 AI 对话的查看入口。主动提交的反馈文字和诊断摘要会提供给管理员，请先检查隐私。</p></details><div class="button-row"><router-link v-if="auth.user" class="btn" to="/feedback">反馈与诊断</router-link><router-link class="btn" to="/welcome">查看产品介绍</router-link><a class="btn" href="https://github.com/oyts/plan-platform" target="_blank" rel="noopener noreferrer">源码与版本记录</a></div></section>
  </div>
</template>
<style scoped>
.help-start{margin-top:28px;display:grid;grid-template-columns:120px minmax(0,1fr);background:var(--paper);border:1px solid var(--line-strong)}.help-number{padding:24px;font-size:3.5rem;color:var(--blue);border-right:1px solid var(--line)}.help-start>div:last-child{padding:24px}.help-start p{max-width:48rem;color:var(--muted)}.help-version-grid{display:grid;grid-template-columns:1fr 1fr}.help-version-grid>div{padding:24px;border-right:1px solid var(--line);min-width:0}.help-version-grid span,.help-capabilities span{color:var(--blue);font-size:.8rem;font-weight:700}.help-version-grid strong{display:block;font-size:2rem;margin:12px 0}.help-version-grid p{color:var(--muted);font-size:.85rem;overflow-wrap:anywhere}.help-note{padding:0 24px;margin:20px 0;color:var(--muted);font-size:.85rem}.help-client-link{margin:0 24px 24px}.help-capabilities{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--line)}.help-capabilities article{padding:24px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);min-width:0}.help-capabilities h3{margin:10px 0}.help-capabilities p{color:var(--muted);font-size:.9rem}.help-answers{padding:24px}.help-answers details{padding:18px 0;border-top:1px solid var(--line)}summary{font-weight:700;cursor:pointer;line-height:1.6}details p{margin:12px 0 0;max-width:64rem;color:var(--muted)}.help-answers .button-row{flex-wrap:wrap;margin-top:20px}.help-answers a{text-decoration:none}@media(max-width:700px){.help-start{grid-template-columns:62px minmax(0,1fr);margin-top:20px}.help-number{font-size:2rem;padding:18px 10px}.help-start>div:last-child,.help-capabilities article,.help-version-grid>div,.help-answers{padding:18px}.help-version-grid,.help-capabilities{grid-template-columns:minmax(0,1fr)}.help-note{padding:0 18px}.help-version-grid>div{border-bottom:1px solid var(--line)}}
</style>
